+    while (true) {
+      const chunk = await aborted(reader.read(), signal);
+      if (chunk.done) break;
+      bytes += chunk.value.byteLength;
+      if (bytes > FAMILY_BATCH_LIMITS.responseBytes) throw new Error("response_too_large");
